import { Application, Container, Sprite, Texture, VideoSource, Graphics, Rectangle } from "pixi.js"
import { AdjustmentFilter, OldFilmFilter, AdvancedBloomFilter, RGBSplitFilter, ZoomBlurFilter, GlitchFilter, MotionBlurFilter } from "pixi-filters"
import { gsap } from "gsap"
import { seededRandom } from "trailer/random"
import { buildText } from "trailer/typography"

// Plays a trailer spec generated by the server (TrailerSpec): footage shots with zoom/pan,
// colour grade, transitions, animated text cards and a music + sound effect mix.
export class TrailerPlayer {
  constructor(spec, host) {
    this.spec = spec
    this.host = host
    this.rng = seededRandom(spec.seed || 1)
    this.videos = []
    this.muted = false
  }

  async load(onProgress = () => {}) {
    const [W, H] = this.spec.size
    this.audio = new (window.AudioContext || window.webkitAudioContext)()
    this.master = this.audio.createGain()
    this.master.connect(this.audio.destination)

    const tasks = [
      ...this.spec.shots.filter((s) => s.type === "clip").map((s) => this.loadVideo(s)),
      ...this.audioUrls().map((url) => this.loadSound(url)),
      ...this.spec.texts.map((t) => document.fonts.load(`${t.weight} 40px "${t.font}"`).catch(() => null))
    ]
    let done = 0
    await Promise.all(tasks.map((p) => p.finally(() => onProgress(++done / tasks.length))))

    this.app = new Application()
    const resolution = Math.min(2.5, Math.max(1, (this.host.clientWidth * (window.devicePixelRatio || 1)) / W))
    await this.app.init({ width: W, height: H, background: "#000000", antialias: true, autoStart: false, resolution, preference: "webgl" })
    this.app.canvas.style.width = "100%"
    this.app.canvas.style.height = "100%"
    this.host.appendChild(this.app.canvas)
    this.buildScene()
  }

  audioUrls() {
    const a = this.spec.audio || {}
    return [a.music?.url, ...(a.sfx || []).map((s) => s.url)].filter(Boolean)
  }

  loadVideo(shot) {
    const video = document.createElement("video")
    Object.assign(video, { muted: true, playsInline: true, preload: "auto", crossOrigin: "anonymous", loop: false })
    video.setAttribute("playsinline", "")
    shot.video = video
    this.videos.push(video)
    return new Promise((resolve) => {
      const ready = () => { video.currentTime = shot.in; video.addEventListener("seeked", resolve, { once: true }) }
      video.addEventListener("loadeddata", ready, { once: true })
      video.addEventListener("error", resolve, { once: true })
      video.src = shot.url
      setTimeout(resolve, 12000)
    })
  }

  async loadSound(url) {
    this.buffers ||= {}
    if (this.buffers[url]) return
    try {
      const data = await (await fetch(url)).arrayBuffer()
      this.buffers[url] = await this.audio.decodeAudioData(data)
    } catch (e) {
      console.warn("trailer audio failed", url, e)
    }
  }

  buildScene() {
    const { spec } = this
    const [W, H] = spec.size
    const g = spec.grade
    const stage = this.app.stage
    this.tl = gsap.timeline({ paused: true })

    // Everything is inside `screen`, which gets film grain + vignette.
    const screen = new Container()
    screen.filterArea = new Rectangle(0, 0, W, H)
    stage.addChild(screen)

    // Footage layer with the colour grade.
    this.world = new Container()
    this.world.filterArea = new Rectangle(0, 0, W, H)
    const tint = hexToRgb(g.tint)
    const mix = (c) => 1 + (c * 1.7 - 1) * g.tint_amount
    const filters = [new AdjustmentFilter({
      saturation: g.saturation, contrast: g.contrast, brightness: g.brightness,
      red: mix(tint.r), green: mix(tint.g), blue: mix(tint.b)
    })]
    if (g.bloom > 0) filters.push(new AdvancedBloomFilter({ threshold: 0.55, bloomScale: g.bloom * 2.2, brightness: 1, blur: 6, quality: 4 }))
    if (g.rgb_split > 0) filters.push(new RGBSplitFilter({ red: { x: -g.rgb_split, y: 0 }, green: { x: 0, y: 0 }, blue: { x: g.rgb_split, y: 0 } }))
    this.world.filters = filters
    screen.addChild(this.world)

    spec.shots.forEach((shot, i) => this.buildShot(shot, i))

    // Transition overlays.
    this.flashLayer = new Graphics().rect(0, 0, W, H).fill(0xffffff)
    this.flashLayer.alpha = 0
    this.blackLayer = new Graphics().rect(0, 0, W, H).fill(0x000000)
    this.blackLayer.alpha = 0
    this.leak = new Sprite(leakTexture())
    this.leak.blendMode = "add"
    this.leak.alpha = 0
    this.leak.height = H * 1.6
    this.leak.width = W * 1.1
    this.leak.anchor.set(0.5)
    this.leak.y = H / 2
    screen.addChild(this.leak, this.flashLayer, this.blackLayer)
    spec.shots.forEach((shot, i) => this.addTransition(shot, i))

    if (spec.letterbox) {
      const bar = H * 0.11
      screen.addChild(new Graphics().rect(0, 0, W, bar).rect(0, H - bar, W, bar).fill(0x000000))
    }

    // Typography above the grade, but still under grain and vignette.
    const texts = new Container()
    screen.addChild(texts)
    spec.texts.forEach((card) => texts.addChild(buildText(spec, card, this.tl, this.rng)))

    this.film = new OldFilmFilter({
      sepia: 0, noise: g.grain, noiseSize: 1, scratch: g.grain > 0.12 ? 0.4 : 0, scratchDensity: 0.25,
      scratchWidth: 1, vignetting: 0.18 + g.vignette * 0.22, vignettingAlpha: Math.min(1, 0.5 + g.vignette * 0.6),
      vignettingBlur: 0.35
    })
    screen.filters = [this.film]

    // Fade in from black and out to black.
    const end = spec.duration
    this.tl.fromTo(screen, { alpha: 0 }, { alpha: 1, duration: 0.4 }, 0)
    this.tl.to(screen, { alpha: 0, duration: 0.5, ease: "power1.in" }, end - 0.5)
    this.tl.set({}, {}, end)
  }

  buildShot(shot, i) {
    const [W, H] = this.spec.size
    const layer = new Container()
    layer.visible = false
    shot.layer = layer
    if (shot.type === "clip" && shot.video?.readyState >= 2) {
      const source = new VideoSource({ resource: shot.video, autoPlay: false, autoLoad: true, updateFPS: 0 })
      const sprite = new Sprite(new Texture({ source }))
      sprite.anchor.set(0.5)
      const cover = Math.max(W / shot.video.videoWidth, H / shot.video.videoHeight)
      const flip = shot.flip ? -1 : 1
      const [z0, z1] = shot.zoom
      const pan = (p, z) => ({ x: W / 2 + p[0] * (z - 1) * W / 2, y: H / 2 + p[1] * (z - 1) * H / 2 })
      const from = pan(shot.pan[0], z0)
      const to = pan(shot.pan[1], z1)
      const span = shot.duration + 0.8
      sprite.position.set(from.x, from.y)
      this.tl.fromTo(sprite.scale, { x: cover * z0 * flip, y: cover * z0 }, { x: cover * z1 * flip, y: cover * z1, duration: span, ease: "none" }, shot.start)
      this.tl.fromTo(sprite.position, from, { ...to, duration: span, ease: "none" }, shot.start)
      layer.addChild(sprite)
      if (shot.dim > 0) {
        const dim = new Graphics().rect(0, 0, W, H).fill(0x000000)
        dim.alpha = 0
        layer.addChild(dim)
        this.tl.to(dim, { alpha: shot.dim, duration: 1.2 }, shot.start + 0.3)
      }
    } else {
      layer.addChild(new Graphics().rect(0, 0, W, H).fill(0x000000))
    }
    this.world.addChild(layer)

    const next = this.spec.shots[i + 1]
    const hideAt = next ? next.start + (next.transition?.duration || 0) : this.spec.duration + 1
    this.tl.set(layer, { visible: true }, shot.start)
    this.tl.set(layer, { visible: false }, hideAt)
  }

  addTransition(shot, i) {
    const { type, duration: d } = shot.transition || { type: "cut", duration: 0 }
    const t = shot.start
    const tl = this.tl
    const [W, H] = this.spec.size
    switch (type) {
      case "dissolve":
        tl.fromTo(shot.layer, { alpha: 0 }, { alpha: 1, duration: d, ease: "none" }, t)
        break
      case "fade_in":
        tl.fromTo(shot.layer, { alpha: 0 }, { alpha: 1, duration: d }, t)
        break
      case "flash":
        tl.fromTo(this.flashLayer, { alpha: 0.95 }, { alpha: 0, duration: d + 0.15, ease: "power2.out", immediateRender: false }, t)
        break
      case "dip_black":
      case "dip_white": {
        const layer = type === "dip_black" ? this.blackLayer : this.flashLayer
        tl.to(layer, { alpha: 1, duration: d / 2, ease: "power1.in" }, t - d / 2)
        tl.to(layer, { alpha: 0, duration: d / 2, ease: "power1.out" }, t)
        break
      }
      case "zoom_blur": {
        const blur = new ZoomBlurFilter({ strength: 0.35, center: { x: W / 2, y: H / 2 }, innerRadius: 20 })
        shot.layer.filters = [blur]
        tl.fromTo(blur, { strength: 0.35 }, { strength: 0, duration: d, ease: "power2.out" }, t)
        tl.set(shot.layer, { filters: null }, t + d)
        break
      }
      case "whip": {
        const blur = new MotionBlurFilter({ velocity: { x: 70, y: 0 }, kernelSize: 15 })
        shot.layer.filters = [blur]
        tl.fromTo(shot.layer, { x: W * 0.35 }, { x: 0, duration: d, ease: "power3.out" }, t)
        tl.to(blur.velocity, { x: 0, duration: d, ease: "power2.out" }, t)
        tl.set(shot.layer, { filters: null }, t + d)
        break
      }
      case "glitch": {
        const glitch = new GlitchFilter({ slices: 10, offset: 30, seed: this.rng() })
        const split = new RGBSplitFilter({ red: { x: -8, y: 2 }, green: { x: 0, y: 0 }, blue: { x: 8, y: -2 } })
        this.world.filters = [...this.world.filters]
        const base = this.world.filters
        tl.set(this.world, { filters: [...base, glitch, split] }, t - 0.08)
        for (let k = 0; k < 5; k++) tl.set(glitch, { seed: this.rng(), offset: this.rng.range(10, 40) }, t - 0.08 + k * 0.06)
        tl.set(this.world, { filters: base }, t + d)
        break
      }
      case "light_leak":
        tl.fromTo(this.leak, { x: -W * 0.2, alpha: 0 }, { x: W * 0.6, alpha: 0.85, duration: d * 0.6, ease: "power1.in", immediateRender: false }, t - d * 0.4)
        tl.to(this.leak, { x: W * 1.1, alpha: 0, duration: d * 0.6, ease: "power1.out" }, t + d * 0.2)
        tl.fromTo(shot.layer, { alpha: 0 }, { alpha: 1, duration: d * 0.5 }, t)
        break
      case "flicker":
        for (let k = 0; k < 4; k++) tl.set(shot.layer, { alpha: k % 2 ? 1 : 0.2 }, t + k * (d / 4))
        tl.set(shot.layer, { alpha: 1 }, t + d)
        break
    }
  }

  play(onEnd) {
    this.stop()
    const now = this.audio.currentTime + 0.12
    this.t0 = now
    this.audio.resume()
    this.scheduleAudio(now)
    this.spec.shots.forEach((s) => { if (s.video) { s.video.pause(); s.video.currentTime = s.in; s.video.playbackRate = s.speed } })
    this.playing = true
    const frame = () => {
      if (!this.playing) return
      const t = Math.max(0, this.audio.currentTime - this.t0)
      this.render(t)
      if (t >= this.spec.duration) {
        this.playing = false
        this.videos.forEach((v) => v.pause())
        // Rest on the title card instead of the final black frame.
        this.tl.seek(Math.max(0, this.spec.duration - 0.7), false)
        this.app.render()
        onEnd?.()
        return
      }
      this.raf = requestAnimationFrame(frame)
    }
    this.raf = requestAnimationFrame(frame)
  }

  render(t) {
    this.syncVideos(t)
    this.tl.seek(Math.min(t, this.spec.duration), false)
    this.film.seed = (Math.floor(t * 24) * 0.618) % 1
    this.app.render()
  }

  // Keep every visible shot's video at the time the spec says it should show.
  syncVideos(t) {
    const shots = this.spec.shots
    shots.forEach((shot, i) => {
      const v = shot.video
      if (!v) return
      const next = shots[i + 1]
      const end = next ? next.start + (next.transition?.duration || 0) + 0.1 : this.spec.duration + 1
      const active = t >= shot.start - 0.05 && t < end
      if (!active) { if (!v.paused) v.pause(); return }
      const expected = shot.in + Math.max(0, t - shot.start) * shot.speed
      if (Math.abs(v.currentTime - expected) > 0.3 && !v.seeking) v.currentTime = Math.min(expected, v.duration - 0.05)
      if (v.paused && v.currentTime < v.duration - 0.05) v.play().catch(() => {})
    })
  }

  scheduleAudio(at) {
    const a = this.spec.audio || {}
    this.sources = []
    const play = (url, when, gain, offset = 0, fadeOutAt = null) => {
      const buffer = this.buffers?.[url]
      if (!buffer) return
      const src = this.audio.createBufferSource()
      src.buffer = buffer
      const gn = this.audio.createGain()
      gn.gain.setValueAtTime(gain, at + when)
      if (fadeOutAt) {
        gn.gain.setValueAtTime(gain, at + fadeOutAt)
        gn.gain.linearRampToValueAtTime(0.0001, at + this.spec.duration)
      }
      src.connect(gn).connect(this.master)
      src.start(at + when, offset)
      this.sources.push(src)
    }
    if (a.music) play(a.music.url, 0, a.music.gain, a.music.offset, this.spec.duration - 1.2)
    ;(a.sfx || []).forEach((s) => play(s.url, s.t, s.gain))
  }

  setMuted(muted) {
    this.muted = muted
    this.master.gain.value = muted ? 0 : 1
  }

  stop() {
    this.playing = false
    cancelAnimationFrame(this.raf)
    ;(this.sources || []).forEach((s) => { try { s.stop() } catch {} })
    this.sources = []
    this.videos.forEach((v) => v.pause())
  }

  destroy() {
    this.stop()
    this.tl?.kill()
    this.app?.destroy(true, { children: true, texture: true })
    this.videos.forEach((v) => { v.removeAttribute("src"); v.load() })
    this.audio?.close()
  }
}

function hexToRgb(hex) {
  const n = parseInt((hex || "#ffffff").slice(1), 16)
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 }
}

let cachedLeak
function leakTexture() {
  if (cachedLeak) return cachedLeak
  const canvas = document.createElement("canvas")
  canvas.width = canvas.height = 256
  const ctx = canvas.getContext("2d")
  const g = ctx.createRadialGradient(128, 128, 0, 128, 128, 128)
  g.addColorStop(0, "rgba(255,190,120,0.95)")
  g.addColorStop(0.4, "rgba(255,120,60,0.5)")
  g.addColorStop(1, "rgba(255,80,40,0)")
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 256, 256)
  cachedLeak = Texture.from(canvas)
  return cachedLeak
}
